def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [b for a, b in history]
    me = [a for a, b in history]

    opp_def = 0
    my_def = 0
    for b in opp:
        if b == 'D':
            opp_def += 1
    for a in me:
        if a == 'D':
            my_def += 1
    opp_c = n - opp_def

    last_me = me[-1]
    last_opp = opp[-1]

    # Count recent behavior (last 12 rounds)
    start = n - 12
    if start < 0:
        start = 0
    rec_opp_d = 0
    rec_my_d = 0
    for i in range(start, n):
        if opp[i] == 'D':
            rec_opp_d += 1
        if me[i] == 'D':
            rec_my_d += 1
    rec_len = n - start

    # Consecutive opponent defections at the end
    consec_opp_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            consec_opp_d += 1
        else:
            break

    # Consecutive mutual defections at the end
    consec_dd = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D' and me[i] == 'D':
            consec_dd += 1
        else:
            break

    # Opponent cooperation rate
    opp_rate = opp_c / n

    # Only one defection seen: likely noise or a test. Forgive fully.
    if opp_def == 1 and n >= 3:
        return 'C'

    # Opponent has never defected: cooperate, but probe sparingly.
    if opp_def == 0:
        if n >= 20 and n % 19 == 0:
            return 'D'
        return 'C'

    # Very hostile opponent: defect most of the time, occasional probe.
    if opp_def * 4 >= n * 3:
        if last_opp == 'C' and rng.random() < 0.08:
            return 'C'
        return 'D'

    # Sustained recent defection: retaliate firmly.
    if consec_opp_d >= 3:
        # Try a single cooperative reset if the streak is long
        if consec_opp_d >= 6 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Mostly cooperative opponent recently: keep cooperating.
    if rec_opp_d * 3 <= rec_len:
        # Break out of mutual defection if stuck
        if consec_dd >= 2:
            return 'C'
        if last_opp == 'D' and consec_opp_d == 1:
            # One recent defection; retaliate only if we were cooperating
            if last_me == 'C':
                if rng.random() < 0.25:
                    return 'C'
                return 'D'
            return 'C'
        return 'C'

    # Moderately defecting opponent: tit-for-tat with forgiveness.
    if last_opp == 'D':
        if consec_dd >= 2:
            # Try to restore cooperation rather than lock in DD
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        if last_me == 'D':
            # We already retaliated last round; return to cooperation
            return 'C'
        # Punish a single defection, then return to C next round
        return 'D'

    # Opponent cooperated last round.
    if last_me == 'D':
        return 'C'
    if opp_rate >= 0.3:
        return 'C'
    if rng.random() < 0.55:
        return 'C'
    return 'D'
